package plates.core.values

/** Anything a flag slot can show: a file a package ships, or a [PlateDrawing]. JSON kinds: "drawing" | "svg" | "raster". */
public sealed interface PlateGraphic

/** A picture built from filled [shapes] in a [width] x [height] space; later shapes cover earlier ones. */
public data class PlateDrawing(val width: Double, val height: Double, val shapes: List<PlateShape>) : PlateGraphic

/** An image a country package ships, addressed by the package that owns it. */
public sealed interface PlateAsset : PlateGraphic {
    public val path: String
    public val packageName: String
}

/** Rasterised at device-pixel size, so a detailed emblem stays crisp at plate scale. */
public data class SvgPlateAsset(override val path: String, override val packageName: String) : PlateAsset

public data class RasterPlateAsset(override val path: String, override val packageName: String) : PlateAsset
